use vstd::prelude::*;

verus! {

fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
    requires
        x.len() > 0,
    ensures
        result.len() == x.len(),
        // For each index i in [0, n), weight is 0.5 if endpoint, else 1.0
        forall(|i: usize| (i < x.len()) ==>
            if i == 0 || i == x.len() - 1 { result[i] == 0.5 } else { result[i] == 1.0 }
        ),
{
    let n = x.len();
    let mut result = Vec::<f32>::with_capacity(n);
    // Invariant ensures result.len() is the current index,
    // and the constructed weights so far satisfy the property
    let mut idx = 0;
    while idx < n
        invariant
            idx <= n,
            result.len() == idx,
            forall(|i: usize| (i < idx) ==>
                if i == 0 || i == n - 1 { result[i] == 0.5 } else { result[i] == 1.0 }
            )
        decreases n - idx,
    {
        if idx == 0 || idx == n - 1 {
            result.push(0.5);
        } else {
            result.push(1.0);
        }
        idx = idx + 1;
    }
    result
}

} 

